function evenOddBit(n) {
  // Read the binary string from its last character backwards.
  const digits = n.toString(2).split('').reverse();
  const result = [0, 0];
  digits.forEach((digit, position) => {
    if (digit === '1') result[position % 2] += 1;
  });
  return result;
}

